/**
 * Table nom de monstre (FR, minuscule, apostrophes typographiques
 * normalisées en apostrophe droite via normalizeWakfuName) -> gfxId + noms
 * EN/ES/PT + image officielle, générée depuis referentiel/monsters_wakfu.json
 * (référentiel complet Ankama fourni par l'utilisateur, 815 monstres) ;
 * remplace l'ancienne table wakfu-monster-images.data.ts (image seule, pas
 * de traduction). En cas de nom en double dans le référentiel source (avant
 * ou après normalisation des apostrophes), la première entrée rencontrée
 * est conservée. `wakassetsAvailable`/`wakfuAvailable` indiquent quelles
 * sources d'image sont valides pour ce monstre (voir shared/entity-icon) :
 * une quinzaine de monstres n'ont d'image valide sur aucune des deux sources.
 */
export interface WakfuMonsterEntry {
  gfxId: string;
  en: string;
  es: string;
  pt: string;
  pictureUrl: string;
  wakassetsAvailable: boolean;
  wakfuAvailable: boolean;
}

